      action: 'returnPortal',
      params: {
        targetDepth: Math.max(0, Math.floor(Number(ticket?.depth || 0))),
        targetX: Math.floor(Number(ticket?.x || 0)),
        targetY: Math.floor(Number(ticket?.y || 0)),
