        at: { x: portalPos.x, y: portalPos.y },
        targetDepth: Math.max(0, Math.floor(Number(ticket?.depth || 0))),
        target: { x: Math.floor(Number(ticket?.x || 0)), y: Math.floor(Number(ticket?.y || 0)) },
