            id: pe?.id || 0,
            to: pe?.pos || null,
            source: pending.source,
            depth: newDepth,
          });
        } catch (e) { console.debug('[transition] emit teleported failed:', e); }
      }
    } finally {
      _inFlight = false;
      armCooldown();
    }
  }

